create table if not exists public.promotion_tesco_category_mappings (
  category_key text primary key,
  tesco_category text not null,
  level_1 text not null,
  updated_at timestamptz not null default now(),
  constraint promotion_tesco_category_mappings_level_1_check check (
    level_1 in ('Baby', 'BWS', 'Celebration', 'Electricals', 'Health & Beauty',
                'Home', 'Outdoor', 'Pet', 'Sports & Leisure', 'Toys')
  )
);

alter table public.promotion_tesco_category_mappings enable row level security;

grant select, insert, update, delete
  on public.promotion_tesco_category_mappings
  to service_role;
revoke all
  on public.promotion_tesco_category_mappings
  from anon, authenticated;

on conflict (category_key) do update set
  tesco_category = excluded.tesco_category,
  level_1 = excluded.level_1,
  updated_at = now();

comment on table public.promotion_tesco_category_mappings is
  'Shared Tesco catalogue category to fixed nomination Level 1 mappings.';
